import { RadioGroup } from '@absoluteui/components/radio-group';

const host = document.createElement('div');
document.body.append(host);
const shipping = RadioGroup.create(host, {
  label: 'Shipping speed',
  name: 'shipping',
  required: true,
  options: [
    { value: 'standard', label: 'Standard', description: '3 to 5 business days' },
    { value: 'express', label: 'Express', description: 'Next business day' },
  ],
});
host.addEventListener('aui-change', () => {
  host.dataset.shipping = shipping.value ?? '';
});

